local({
  group <- coalesce(
    if_else(V26 == "Other*", lookup_values(V27, lookup_ethnicity_other), NA_character_),
    lookup_values(V26, lookup_ethnicity, dataset_id = spec$dataset_id, target_variable = "ethnicity")
  )
  case_when(group == "White" ~ "Non-minority", !is.na(group) ~ "Minority", .default = "Unknown")
})

local({
  uk <- "UK-CDI words produced, 6-18 months, 392 words in the paper (395 in the study's percentage column), marked understands and says (range 0-392 or 0-395), count; missing-item rule not documented"
  lincoln <- "Lincoln UK-CDI Toddlers words produced, 19-36 months, 663 words in the paper (690 in the study's percentage column), marked understands and says (range 0-663 or 0-690), count; missing-item rule not documented"
  case_when(!is.na(UKCDIUS) ~ uk, !is.na(LincolnCDIUS) ~ lincoln, .default = NA_character_)
})
